insert into public.commercial_lines(code,name) select code,name from jsonb_to_recordset($data$[{"code":"AVI","name":"Avisos en sustrato"},{"code":"EST","name":"Estructuras publicitarias"},{"code":"INT","name":"Registros internos"},{"code":"LED","name":"Tecnología LED"},{"code":"LIT","name":"Impresos litográficos"},{"code":"LON","name":"Impresión en lona"},{"code":"OOH","name":"Alquiler y pauta exterior"},{"code":"PRO","name":"Promocionales"},{"code":"SEN","name":"Señalización"},{"code":"SER","name":"Servicios técnicos"},{"code":"UT","name":"Aplicaciones de transporte UT"},{"code":"VIN","name":"Vinilos y corte"}]$data$::jsonb) as x(code text,name text) on conflict(code) do update set name=excluded.name;
insert into public.product_families(code,name) select code,name from jsonb_to_recordset($data$[{"code":"FAM-AVI-AVISOS-SOBRE-SOPORTE","name":"Avisos sobre soporte"},{"code":"FAM-EST-BACKINGS","name":"Backings"},{"code":"FAM-EST-BASTIDORES","name":"Bastidores"},{"code":"FAM-EST-ESTRUCTURAS-PARA-LED","name":"Estructuras para LED"},{"code":"FAM-EST-PUBLIPOSTES","name":"Publipostes"},{"code":"FAM-EST-TROQUELES-PARA-VALLA","name":"Troqueles para valla"},{"code":"FAM-EST-VALLAS-DE-CERCHA","name":"Vallas de cercha"},{"code":"FAM-INT-COTIZACIÓN-MANUAL","name":"Cotización manual"},{"code":"FAM-INT-RECARGAS-Y-GASTOS","name":"Recargas y gastos"},{"code":"FAM-LED-PANTALLAS-LED","name":"Pantallas LED"},{"code":"FAM-LIT-LITOGRAFÍA","name":"Litografía"},{"code":"FAM-LON-LONA-IMPRESA","name":"Lona impresa"},{"code":"FAM-LON-PASACALLES","name":"Pasacalles"},{"code":"FAM-LON-PENDONES","name":"Pendones"},{"code":"FAM-OOH-PAQUETES-DE-UBICACIONES","name":"Paquetes de ubicaciones"},{"code":"FAM-OOH-UBICACIONES-DE-VALLA","name":"Ubicaciones de valla"},{"code":"FAM-PRO-SOUVENIRS","name":"Souvenirs"},{"code":"FAM-SEN-SEÑALES-Y-SEÑALIZACIÓN","name":"Señales y señalización"},{"code":"FAM-SER-DESINSTALACIÓN","name":"Desinstalación"},{"code":"FAM-SER-INSTALACIÓN","name":"Instalación"},{"code":"FAM-SER-MANTENIMIENTO","name":"Mantenimiento"},{"code":"FAM-SER-VISITAS-TÉCNICAS","name":"Visitas técnicas"},{"code":"FAM-UT-APLICACIONES-EN-ESTACIONES","name":"Aplicaciones en estaciones"},{"code":"FAM-UT-DOMINACIÓN-DE-ESPACIOS","name":"Dominación de espacios"},{"code":"FAM-UT-PANELES-Y-LONAS-UT","name":"Paneles y lonas UT"},{"code":"FAM-UT-VEHÍCULOS","name":"Vehículos"},{"code":"FAM-VIN-VINILOS","name":"Vinilos"}]$data$::jsonb) as x(code text,name text) on conflict(code) do update set name=excluded.name;
insert into public.product_types(code,name,quote_mode) select code,name,case code when 'CONFIGURABLE' then 'configurable' when 'UBICACION' then 'asset' when 'PAQUETE' then 'package' else 'review' end from jsonb_to_recordset($data$[{"code":"CONFIGURABLE","name":"Producto configurable"},{"code":"UBICACION","name":"Ubicación"},{"code":"SERVICIO","name":"Servicio"},{"code":"INTERNO","name":"Registro interno"},{"code":"PENDIENTE","name":"Producto por definir"},{"code":"PAQUETE","name":"Paquete"}]$data$::jsonb) as x(code text,name text) on conflict(code) do update set name=excluded.name;
